describe('Async Operation Cancellation with Abort Button', () => {
  beforeEach(() => {
    cy.visit('/async-operation');
  });

  it('should cancel an async operation when Abort button is clicked', () => {
    // Intercept the async API call
    cy.intercept('GET', '/api/data', (req) => {
      req.reply((res) => {
        res.delay(5000);
      });
    }).as('fetchData');

    // Click the button to start the async operation
    cy.get('[data-testid="start-async-button"]').click();

    // Verify the operation has started
    cy.get('[data-testid="loading-indicator"]').should('be.visible');
    cy.get('[data-testid="result-message"]').should('contain', 'Loading...');

    // Click the Abort button
    cy.get('[data-testid="abort-button"]').click();

    // Verify the operation was cancelled
    cy.get('[data-testid="loading-indicator"]').should('not.exist');
    cy.get('[data-testid="result-message"]').should('contain', 'Operation cancelled');
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Request aborted');
  });

  it('should complete async operation when Abort button is not clicked', () => {
    // Intercept the async API call
    cy.intercept('GET', '/api/data', {
      statusCode: 200,
      body: { data: 'Operation completed successfully' },
      delay: 1000
    }).as('fetchData');

    // Click the button to start the async operation
    cy.get('[data-testid="start-async-button"]').click();

    // Wait for the operation to complete
    cy.wait('@fetchData');

    // Verify the operation completed successfully
    cy.get('[data-testid="loading-indicator"]').should('not.exist');
    cy.get('[data-testid="result-message"]').should('contain', 'Operation completed successfully');
    cy.get('[data-testid="error-message"]').should('not.exist');
  });
});
